#include "baseline_registry.hpp"

#include <algorithm>

#include "all_baselines.hpp"      // generated by CMake from include/baselines/*.hpp

namespace
{
    template <BaselineLine L>
    class LineAdapter : public AnyLine
    {
    public:
        explicit LineAdapter(L line) : line_(std::move(line)) {}
        void update(const Bar& bar) override { line_.update(bar); }
        bool ready() const override { return line_.ready(); }
        double value() const override { return line_.value(); }
        std::unique_ptr<AnyLine> clone() const override { return std::make_unique<LineAdapter>(*this); }
    private:
        L line_;
    };

    template <BaselineDefinition S>
    BaselineInfo describe(const std::string& name)
    {
        using Line = typename S::Line;

        BaselineInfo info;
        info.name = name;
        info.ranges = S::ranges();
        info.warmupBars = [](const Params& p) { return static_cast<std::size_t>(S::warmup(p)); };
        info.makeLine = [](const Params& p) -> std::unique_ptr<AnyLine>
        {
            return std::make_unique<LineAdapter<Line>>(S::make(p));
        };
        info.nnfx = [](const NnfxOptions& options) -> StrategyFactory
        {
            return [options](const Params& p, std::size_t assets) -> std::unique_ptr<MultiStrategy>
            {
                return std::make_unique<NnfxStrategy<Line>>(assets, S::make(p), options);
            };
        };
        return info;
    }

    std::vector<BaselineInfo> build()
    {
        std::vector<BaselineInfo> all;
        forEachBaseline([&](const char* name, auto tag)
        {
            all.push_back(describe<typename decltype(tag)::type>(name));
        });
        std::sort(all.begin(), all.end(), [](const BaselineInfo& a, const BaselineInfo& b) { return a.name < b.name; });
        return all;
    }
}

const std::vector<BaselineInfo>& baselineRegistry()
{
    static const std::vector<BaselineInfo> all = build();
    return all;
}

const BaselineInfo* findBaseline(const std::string& name)
{
    for (const BaselineInfo& b : baselineRegistry())
    {
        if (b.name == name)
            return &b;
    }
    return nullptr;
}

std::string baselineNames()
{
    std::string out;
    for (const BaselineInfo& b : baselineRegistry())
        out += (out.empty() ? "" : ", ") + b.name;
    return out;
}
